package com.pulsesg.support.controller;
import com.pulsesg.support.dto.ApiDtos.*; import com.pulsesg.support.service.PortalService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import com.pulsesg.support.security.JwtService;
@RestController @RequestMapping("/api/auth") public class AuthController {private final PortalService service;private final JwtService jwt;public AuthController(PortalService s,JwtService j){service=s;jwt=j;}@PostMapping("/register") ResponseEntity<AuthResponse> register(@Valid @RequestBody RegisterRequest r){var u=service.register(r);return ResponseEntity.status(201).body(new AuthResponse(jwt.create(u.getEmail()),service.user(u)));}@PostMapping("/login") AuthResponse login(@Valid @RequestBody AuthRequest r){if(!service.valid(r.email(),r.password()))throw new org.springframework.security.authentication.BadCredentialsException("Invalid email or password");var u=service.byEmail(r.email());return new AuthResponse(jwt.create(u.getEmail()),service.user(u));}@GetMapping("/me") UserResponse me(){return service.user(service.current());}}
